EMD = "\u2014"  # —
LSQ, RSQ = "\u2018", "\u2019"  # ' '
LDQ, RDQ = "\u201c", "\u201d"  # " "


def sq(s):  # curly single quotes around s
    return LSQ + s + RSQ


def dq(s):  # curly double quotes around s
    return LDQ + s + RDQ


