# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    with open(PATH, encoding="utf-8") as f:
        data = json.load(f)

    topics = {t["num"]: t for t in data["topics"]}
    assert len(topics) == 14, "expected 14 topics"

    # repairs (truncated strings -> full text)
    for (num, idx), (prefix, new) in sorted(REPAIRS.items()):
        old = topics[num]["key_concepts"][idx]
        assert old.startswith(prefix.rstrip()), "prefix mismatch at topic %d C%d: %r" % (num, idx, old[:60])
        assert old.rstrip().endswith("..."), "expected truncated string at topic %d C%d" % (num, idx)
        topics[num]["key_concepts"][idx] = new

    # rewrites (exact replacements of complete strings)
    for (num, idx), (old_text, new) in sorted(REWRITES.items()):
        old = topics[num]["key_concepts"][idx]
        assert old == old_text, "rewrite mismatch at topic %d C%d: %r" % (num, idx, old[:80])
        topics[num]["key_concepts"][idx] = new

    # additions (dedupe by first 60 chars)
    for num, new_concepts in sorted(ADDITIONS.items()):
        existing = topics[num]["key_concepts"]
        for c in new_concepts:
            key = c[:60]
            if any(e[:60] == key for e in existing):
                print("SKIP duplicate concept in topic", num, key)
                continue
            existing.append(c)

    # new questions (dedupe by qnum and by question prefix)
    existing_qnums = {q["qnum"] for t in data["topics"] for q in t["questions"]}
    for num, qs in sorted(NEW_QUESTIONS.items()):
        for q in qs:
            assert q["qnum"] not in existing_qnums, "qnum clash: " + q["qnum"]
            if any(ex["question"][:60] == q["question"][:60] for t in data["topics"] for ex in t["questions"]):
                print("SKIP duplicate question", q["qnum"])
                continue
            topics[num]["questions"].append(q)
            existing_qnums.add(q["qnum"])

    # topic 15
    assert 15 not in topics
    data["topics"].append(TOPIC_15)

    with open(PATH, "w", encoding="utf-8", newline="\n") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write("\n")

    total_q = sum(len(t["questions"]) for t in data["topics"])
    print("OK: topics=%d questions=%d" % (len(data["topics"]), total_q))
    for t in data["topics"]:
        print("  topic %2d: %2d concepts, %d questions" % (t["num"], len(t["key_concepts"]), len(t["questions"])))


if __name__ == "__main__":
    sys.exit(main())
